<?php require __DIR__.'/_init.php'; $errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $name=trim($_POST['full_name']??'');$user=trim($_POST['username']??'');$email=trim($_POST['email']??'');$reg=trim($_POST['student_number']??'');$pass=$_POST['password']??'';if(mb_strlen($name)<2)$errors[]='Enter your full name.';if(!preg_match('/^[A-Za-z0-9_]{3,40}$/',$user))$errors[]='Username must be 3–40 letters, digits or underscores.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if($reg==='')$errors[]='Enter your student number.';if(strlen($pass)<10)$errors[]='Password must be at least 10 characters.';if(!hash_equals($pass,$_POST['confirm']??''))$errors[]='Passwords do not match.';if(!$errors){try{$s=db()->prepare('INSERT INTO users(full_name,username,email,student_number,password_hash) VALUES(?,?,?,?,?)');$s->execute([$name,$user,$email,$reg,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Sign in to continue.');header('Location: /login.php');exit;}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'That username, email or student number is already registered.':'Registration could not be completed.';}}} page_start('Create account'); ?><section class="form-wrap"><div class="eyebrow">STUDENT ACCOUNT</div><h1>Join CampusFlow</h1><p>Use your official student details to get started.</p><?php foreach($errors as $x)echo '<p class="error">'.e($x).'</p>'; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><?php foreach(['full_name'=>'Full name','username'=>'Username','email'=>'Email address','student_number'=>'Student number'] as $n=>$l):?><label><?=$l?><input name="<?=$n?>" value="<?=e($_POST[$n]??'')?>" required></label><?php endforeach;?><label>Password<input type="password" name="password" minlength="10" required></label><label>Confirm password<input type="password" name="confirm" required></label><button class="button">Create account →</button></form></section><?php page_end(); ?>
